    [Theory]
    [MemberData(nameof(Searches))]
    public void AWayThroughAPlaceWhosePartsDoNotMeetIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The searches whose parts meet; one adding them the other way round; one whose middle place is named via; two tables
    /// multiplied the min-plus way, each part from its own; and the places reachable from each other, with and and or.
    /// </summary>
